challenge.solution:
def puede_circular(placa, dia="lunes"):
    ultimo = placa[-1]
    if dia == "lunes":
        return ultimo not in "12"
    elif dia == "martes":
        return ultimo not in "34"
    elif dia == "miercoles":
        return ultimo not in "56"
    elif dia == "jueves":
        return ultimo not in "78"
    elif dia == "viernes":
        return ultimo not in "90"
    return True

def mensaje(placa, dia="lunes"):
    if puede_circular(placa, dia):
        return "Puede circular"
    return "Tiene restricción"

print(mensaje("BCD123", "martes"))
print(mensaje("BCD123", "miercoles"))
print(mensaje("ABC788", "jueves"))
print(mensaje("ABC788"))
print(mensaje("XYZ440", "sabado"))

