import math

def factorial_rec(n):
    if n == 0:
        return 1
    return n * factorial_rec(n - 1)

def factorial_bucle(n):
    resultado = 1
    for i in range(2, n + 1):
        resultado *= i
    return resultado

for n in (0, 1, 5, 10):
    assert factorial_rec(n) == factorial_bucle(n) == math.factorial(n)
    print(f"{n}! = {factorial_rec(n)}")
print("Pruebas OK")

challenge.solution:
def invertir(texto):
    """Devuelve el texto al revés usando recursión."""
    if texto == "":
        return ""
    return invertir(texto[1:]) + texto[0]

def suma_digitos(n):
    """Suma los dígitos de un entero positivo."""
    if n < 10:
        return n
    return n % 10 + suma_digitos(n // 10)

def es_palindromo(texto):
    limpio = texto.lower().replace(" ", "")
    return limpio == invertir(limpio)

print(invertir("curso"))
print(suma_digitos(4507))
print(es_palindromo("reconocer"), es_palindromo("python"))
assert invertir("curso") == "osruc"
assert invertir("") == ""
assert suma_digitos(4507) == 16
assert suma_digitos(7) == 7
assert es_palindromo("reconocer")
assert not es_palindromo("python")
print("Pruebas OK")

