challenge.solution:
def diferencias(a, b):
    claves = list(a.keys()) + [k for k in b if k not in a]
    resultado = {}
    for k in claves:
        va = a.get(k)
        vb = b.get(k)
        if va != vb:
            resultado[k] = (va, vb)
    return resultado

a = {"nombre": "Ana", "ciudad": "Cartago", "telefono": "8888-1234"}
b = {"nombre": "Ana", "ciudad": "Heredia", "correo": "ana@correo.cr"}
cambios = diferencias(a, b)
for campo, (antes, despues) in cambios.items():
    print(f"{campo:10} {antes} -> {despues}")
assert sorted(cambios.keys()) == ["ciudad", "correo", "telefono"]
assert cambios["ciudad"] == ("Cartago", "Heredia")
assert cambios["telefono"] == ("8888-1234", None)
assert diferencias(a, a) == {}
print("Pruebas OK")

