VACIAS = {"el", "la", "de", "y", "en", "un", "una", "los", "las", "que"}

def top_palabras(texto, n):
    conteo = {}
    for pieza in texto.split():
        palabra = pieza.strip(",.;:!?").lower()
        if palabra in VACIAS or palabra == "":
            continue
        conteo[palabra] = conteo.get(palabra, 0) + 1
    pares = sorted(conteo.items(), key=lambda par: (-par[1], par[0]))
    return pares[:n]

