DIAS = {"1": "lunes", "2": "lunes", "3": "martes", "4": "martes", "5": "miércoles",
        "6": "miércoles", "7": "jueves", "8": "jueves", "9": "viernes", "0": "viernes"}
ORDEN = ["lunes", "martes", "miércoles", "jueves", "viernes"]

def es_placa_valida(placa):
    return len(placa) == 6 and placa[:3].isalpha() and placa[3:].isdigit()

def dia_restriccion(placa):
    return DIAS[placa[-1]]

def reporte(placas):
    distintas = {p.strip().upper() for p in placas}
    por_dia = {}
    invalidas = []
    for placa in sorted(distintas):
        if not es_placa_valida(placa):
            invalidas.append(placa)
            continue
        por_dia.setdefault(dia_restriccion(placa), []).append(placa)
    return por_dia, invalidas

placas = ["BCD123", "xyz889", "BCD123", "KLM456", "QRS110", "AB1234", "TUV777", "klm456"]
por_dia, invalidas = reporte(placas)
assert por_dia["martes"] == ["BCD123"]
assert por_dia["viernes"] == ["QRS110", "XYZ889"]
assert invalidas == ["AB1234"]
for dia in ORDEN:
    lista = por_dia.get(dia, [])
    print(dia.ljust(10) + ", ".join(lista))
print("Inválidas:", ", ".join(invalidas))

