import csv
import os

class MontoInvalido(Exception):
    pass

def validar_fila(fila):
    if not fila["categoria"].strip():
        raise MontoInvalido("categoría vacía")
    try:
        valor = int(fila["valor"])
    except ValueError:
        raise MontoInvalido(f"'{fila['valor']}' no es un entero")
    if valor <= 0:
        raise MontoInvalido(f"el valor debe ser mayor que 0, llegó {valor}")
    return {"fecha": fila["fecha"], "categoria": fila["categoria"], "valor": valor}

def cargar_gastos_seguro(ruta):
    gastos, errores = [], []
    try:
        with open(ruta, newline="", encoding="utf-8") as f:
            for numero, fila in enumerate(csv.DictReader(f), start=2):
                try:
                    gastos.append(validar_fila(fila))
                except MontoInvalido as e:
                    errores.append(f"línea {numero}: {e}")
    except FileNotFoundError:
