    try:
        monto = float(texto)
    except ValueError:
        raise MontoInvalido(f"'{texto}' no es un número")
    if monto <= 0:
        raise MontoInvalido(f"el monto debe ser mayor que 0, llegó {monto}")
    return monto

def cargar_gastos(ruta=RUTA):
    if not os.path.exists(ruta):
        return []
    with open(ruta, newline="", encoding="utf-8") as f:
        gastos = list(csv.DictReader(f))
    for g in gastos:
        g["valor"] = float(g["valor"])
    return gastos

def guardar_gastos(gastos, ruta=RUTA):
    os.makedirs(os.path.dirname(ruta), exist_ok=True)
    with open(ruta, "w", newline="", encoding="utf-8") as f:
        escritor = csv.DictWriter(f, fieldnames=COLUMNAS)
        escritor.writeheader()
        escritor.writerows(gastos)

