def por_categoria(gastos):
    totales = {}
    for g in gastos:
        totales[g["categoria"]] = totales.get(g["categoria"], 0) + g["valor"]
    return totales

def por_mes(gastos):
    totales = {}
    for g in gastos:
        mes = g["fecha"][:7]
        totales[mes] = totales.get(mes, 0) + g["valor"]
    return totales

def resumen(gastos):
    if not gastos:
        return "Sin gastos registrados"
    lineas = []
    meses = por_mes(gastos)
    for mes in sorted(meses):
        lineas.append(f"{mes}: {meses[mes]:,.0f}")
    categorias = por_categoria(gastos)
    mayor = max(categorias, key=categorias.get)
    lineas.append(f"Mayor gasto: {mayor} ({categorias[mayor]:,.0f})")
    return "\n".join(lineas)

