class Cuenta:
    """Cuenta de una mesa en una soda."""

    def __init__(self, mesa):
        self.mesa = mesa
        self.items = []

    def agregar(self, nombre, precio):
        self.items.append((nombre, precio))

    def subtotal(self):
        return sum(precio for _, precio in self.items)

    def total(self):
        sub = self.subtotal()
        return round(sub + sub * 0.13 + sub * 0.10)

    def __str__(self):
        lineas = [f"Mesa {self.mesa}"]
        for nombre, precio in self.items:
            lineas.append(f"  {nombre:<10} {precio:>6,}")
        lineas.append(f"  Subtotal   {self.subtotal():>6,}")
        lineas.append(f"  Total      {self.total():>6,}")
        return "\n".join(lineas)

