class SinCombustible(Exception):
    pass

class Tanque:
    def __init__(self, capacidad, litros=0):
        self._capacidad = capacidad
        self.litros = litros

    @property
    def capacidad(self):
        return self._capacidad

    @property
    def litros(self):
        return self._litros

    @litros.setter
    def litros(self, valor):
        if valor < 0:
            raise ValueError("Los litros no pueden ser negativos")
        if valor > self._capacidad:
            raise ValueError(f"El tanque solo tiene capacidad para {self._capacidad} litros")
        self._litros = valor

    @property
    def porcentaje(self):
        return round(self._litros / self._capacidad * 100)

    def cargar(self, litros):
        self.litros = self.litros + litros

    def consumir(self, km, rendimiento):
        necesarios = km / rendimiento
        if necesarios > self._litros:
            raise SinCombustible(f"Necesitas {necesarios:.1f} litros y tienes {self._litros:.1f}")
        self._litros -= necesarios

