class Presupuesto:
    """Un mes de gastos: contiene una lista de objetos Gasto."""

    def __init__(self, mes, limite):
        self.mes = mes
        self.limite = limite
        self.gastos = []           # una lista nueva por presupuesto

    def agregar(self, gasto):
        self.gastos.append(gasto)

    def total(self):
        return sum(g.valor for g in self.gastos)

    def por_categoria(self):
        totales = {}
        for g in self.gastos:
            totales[g.categoria] = totales.get(g.categoria, 0) + g.valor
        return totales

    def disponible(self):
        return self.limite - self.total()

    def __str__(self):
        lineas = [f"Presupuesto {self.mes}"]
        for g in self.gastos:
            lineas.append(f"  {g}")       # delega en Gasto.__str__
        lineas.append(f"  Total: {self.total():,} de {self.limite:,}")
        return "\n".join(lineas)

