        return f"{self.titulo} ({estado})"

class Socio:
    MAXIMO = 3

    def __init__(self, nombre):
        self.nombre = nombre
        self.prestamos = []

    def puede_pedir(self):
        return len(self.prestamos) < Socio.MAXIMO

class Prestamo:
    def __init__(self, libro, socio, fecha):
        self.libro = libro
        self.socio = socio
        self.fecha = fecha

class Biblioteca:
    def __init__(self):
        self.libros = []
        self.socios = []

    def prestar(self, socio, libro, fecha):
        if not libro.disponible:
            raise LibroNoDisponible(f"{libro.titulo} ya esta prestado")
        if not socio.puede_pedir():
            raise LimiteDePrestamos(f"{socio.nombre} ya tiene {Socio.MAXIMO} prestamos")
        prestamo = Prestamo(libro, socio, fecha)
        libro.disponible = False
        socio.prestamos.append(prestamo)
        return prestamo

    def devolver(self, prestamo):
