class SinEspacio(Exception):
    pass

class Vehiculo:
    def __init__(self, placa, tipo):
        self.placa = placa
        self.tipo = tipo

class Espacio:
    def __init__(self, numero):
        self.numero = numero
        self.vehiculo = None

    def libre(self):
        return self.vehiculo is None

class Ticket:
    def __init__(self, vehiculo, espacio, minuto_entrada):
        self.vehiculo = vehiculo
        self.espacio = espacio
        self.minuto_entrada = minuto_entrada

class Parqueo:
    TARIFAS = {"carro": 700, "moto": 400}

    def __init__(self, cantidad):
        self.espacios = [Espacio(n) for n in range(1, cantidad + 1)]

    def entrar(self, vehiculo, minuto):
        for e in self.espacios:
            if e.libre():
                e.vehiculo = vehiculo
                return Ticket(vehiculo, e, minuto)
        raise SinEspacio(f"No hay espacio para {vehiculo.placa}")

    def salir(self, ticket, minuto):
        minutos = minuto - ticket.minuto_entrada
        horas = (minutos + 59) // 60
        ticket.espacio.vehiculo = None
        return Parqueo.TARIFAS[ticket.vehiculo.tipo] * max(horas, 1)

