class SaldoInsuficiente(Exception):
    pass

class CuentaBancaria:
    def __init__(self, titular, saldo_inicial=0):
        self.titular = titular
        self._saldo = saldo_inicial

    @property
    def saldo(self):
        return self._saldo

    def depositar(self, monto):
        if monto <= 0:
            raise ValueError("El deposito debe ser positivo")
        self._saldo += monto

    def retirar(self, monto):
        if monto > self._saldo:
            raise SaldoInsuficiente(f"Saldo {self._saldo:,}, retiro {monto:,}")
        self._saldo -= monto

    def __str__(self):
        return f"{type(self).__name__} de {self.titular}: {self._saldo:,}"

class CuentaAhorro(CuentaBancaria):
    def __init__(self, titular, saldo_inicial, tasa):
        super().__init__(titular, saldo_inicial)
        self.tasa = tasa
        self.retiros = 0

    def aplicar_interes(self):
        self._saldo += round(self._saldo * self.tasa / 100)

    def retirar(self, monto):
        if self.retiros >= 3:
            raise ValueError("Maximo 3 retiros al mes")
        super().retirar(monto)
        self.retiros += 1

class CuentaCorriente(CuentaBancaria):
    def __init__(self, titular, saldo_inicial, sobregiro):
        super().__init__(titular, saldo_inicial)
        self.sobregiro = sobregiro

    def retirar(self, monto):
        if monto > self._saldo + self.sobregiro:
            raise SaldoInsuficiente(f"Supera el sobregiro de {self.sobregiro:,}")
        self._saldo -= monto

ahorro = CuentaAhorro("Tomas", 100000, 2)
ahorro.aplicar_interes()
assert ahorro.saldo == 102000
for _ in range(3):
    ahorro.retirar(1000)
cuarto = False
try:
    ahorro.retirar(1000)
except ValueError:
    cuarto = True
assert cuarto and ahorro.saldo == 99000

corriente = CuentaCorriente("Ana", 10000, 5000)
corriente.retirar(14000)
assert corriente.saldo == -4000
excedido = False
try:
    corriente.retirar(2000)
except SaldoInsuficiente:
    excedido = True
assert excedido
assert isinstance(ahorro, CuentaBancaria) and isinstance(corriente, CuentaBancaria)
print(ahorro)
print(corriente)

