from collections import Counter

@dataclass
class Gasto:
    descripcion: str
    valor: int
    categoria: str = "otros"

gastos = [
    Gasto("Café", 1200, "comida"), Gasto("Bus", 650, "transporte"),
    Gasto("Café", 1300, "comida"), Gasto("Almuerzo", 3500, "comida"),
    Gasto("Bus", 650, "transporte"), Gasto("Café", 1200, "comida"),
    Gasto("Pan", 900, "comida"), Gasto("Bus", 700, "transporte"),
]

def mas_repetido(gastos):
    conteo = Counter(g.descripcion for g in gastos)
    return conteo.most_common(1)[0][0]

def ordenar_por_frecuencia(gastos):
    conteo = Counter(g.descripcion for g in gastos)
    return sorted(gastos, key=lambda g: (-conteo[g.descripcion], g.valor))

print("Más repetido:", mas_repetido(gastos))
for g in ordenar_por_frecuencia(gastos):
    print(g.descripcion, g.valor)

