import pytest

class Presupuesto:
    def __init__(self, limite):
        self.limite = limite
        self.gastos = []

    def agregar(self, valor):
        if self.total() + valor > self.limite:
            raise ValueError("supera el límite")
        self.gastos.append(valor)

    def total(self):
        return sum(self.gastos)

    def disponible(self):
        # Error original: devolvía 0 cuando no había gastos.
        return self.limite - self.total()


def test_presupuesto_nuevo_tiene_total_cero():
    assert Presupuesto(10000).total() == 0


