import time

def duplicados_lento(valores):
    repetidos = []
    for i in range(len(valores)):
        for j in range(i + 1, len(valores)):
            if valores[i] == valores[j] and valores[i] not in repetidos:
                repetidos.append(valores[i])
    return repetidos

def duplicados_rapido(valores):
    vistos = set()
    repetidos = []
    for v in valores:
        if v in vistos and v not in repetidos:
            repetidos.append(v)
        vistos.add(v)
    return repetidos

datos = list(range(3000)) + [5, 77, 1200]
assert duplicados_lento(datos) == duplicados_rapido(datos) == [5, 77, 1200]
