class PilaVacia(Exception):
    pass


class Pila:
    """Pila LIFO sobre una lista: push, pop y peek son O(1)."""

    def __init__(self):
        self._datos = []

    def push(self, elemento):
        self._datos.append(elemento)

    def pop(self):
        if self.esta_vacia():
            raise PilaVacia("no se puede hacer pop en una pila vacía")
        return self._datos.pop()

    def peek(self):
        if self.esta_vacia():
            raise PilaVacia("la pila está vacía")
        return self._datos[-1]

    def esta_vacia(self):
        return len(self._datos) == 0

    def __len__(self):
        return len(self._datos)


