class PilaVacia(Exception):
    """Se lanza al hacer pop o peek en una pila sin elementos."""


class Pila:
    def __init__(self):
        self._datos = []

    def push(self, x):
        """Apila x en la cima. O(1)."""
        self._datos.append(x)

    def pop(self):
        """Quita y devuelve la cima. O(1). Lanza PilaVacia si no hay elementos."""
        if not self._datos:
            raise PilaVacia("pop en pila vacía")
        return self._datos.pop()

    def peek(self):
        """Devuelve la cima sin quitarla. O(1)."""
        if not self._datos:
            raise PilaVacia("peek en pila vacía")
        return self._datos[-1]

    def esta_vacia(self):
        return not self._datos

    def __len__(self):
        return len(self._datos)


p = Pila()
p.push(10)
p.push(20)
assert p.peek() == 20 and len(p) == 2
assert p.pop() == 20 and p.pop() == 10
assert p.esta_vacia()
try:
    p.pop()
except PilaVacia as e:
    print("Correcto, lanzó:", e)

def balanceada(expresion):
    pares = {")": "(", "]": "[", "}": "{"}
    pila = []
    for c in expresion:
        if c in "([{":
            pila.append(c)
        elif c in pares:
            if not pila or pila[-1] != pares[c]:
                return False
            pila.pop()
    return not pila


