from collections import deque


class ColaVacia(Exception):
    pass


class Cola:
    """Cola FIFO sobre deque: encolar y desencolar son O(1)."""

    def __init__(self):
        self._datos = deque()

    def encolar(self, elemento):
        self._datos.append(elemento)

    def desencolar(self):
        if self.esta_vacia():
            raise ColaVacia("no hay nadie en la fila")
        return self._datos.popleft()

    def frente(self):
        if self.esta_vacia():
            raise ColaVacia("la fila está vacía")
        return self._datos[0]

    def esta_vacia(self):
        return len(self._datos) == 0

    def __len__(self):
        return len(self._datos)


