from collections import deque


class ColaVacia(Exception):
    """Se lanza al desencolar o mirar el frente de una cola vacía."""


class Cola:
    def __init__(self):
        self._datos = deque()

    def encolar(self, x):
        """Agrega x al final. O(1)."""
        self._datos.append(x)

    def desencolar(self):
        """Quita y devuelve el del frente. O(1). Lanza ColaVacia si está vacía."""
        if not self._datos:
            raise ColaVacia("desencolar en cola vacía")
        return self._datos.popleft()

    def frente(self):
        """Devuelve el del frente sin quitarlo. O(1)."""
        if not self._datos:
            raise ColaVacia("frente en cola vacía")
        return self._datos[0]

    def esta_vacia(self):
        return not self._datos

    def __len__(self):
        return len(self._datos)


c = Cola()
c.encolar("a")
c.encolar("b")
assert c.frente() == "a" and len(c) == 2
assert c.desencolar() == "a" and c.desencolar() == "b"
assert c.esta_vacia()
try:
    c.frente()
except ColaVacia as e:
    print("Correcto, lanzó:", e)

