def evaluar_rpn(expresion):
    pila = []
    for token in expresion.split():
        if token in "+-*/":
            if len(pila) < 2:
                raise ValueError(f"faltan operandos para '{token}'")
            b = pila.pop()
            a = pila.pop()
            if token == "+":
                pila.append(a + b)
            elif token == "-":
                pila.append(a - b)
            elif token == "*":
                pila.append(a * b)
            else:
                pila.append(a / b)
        else:
            pila.append(float(token))
    if len(pila) != 1:
        raise ValueError(f"expresión incompleta: quedan {len(pila)} valores en la pila")
    return pila[0]


assert evaluar_rpn("3 4 +") == 7
assert evaluar_rpn("5 1 2 + 4 * + 3 -") == 14
assert evaluar_rpn("2 3 4 * +") == 14
assert evaluar_rpn("10 4 /") == 2.5
for invalida in ("1 +", "1 2"):
    try:
        evaluar_rpn(invalida)
        print("no debería llegar aquí")
    except ValueError as e:
        print(f"{invalida!r}: {e}")
print("5 1 2 + 4 * + 3 - =", evaluar_rpn("5 1 2 + 4 * + 3 -"))

