class ArbolBinario:
    def __init__(self):
        self.raiz = None

    def insertar(self, valor):
        self.raiz = self._insertar(self.raiz, valor)

    def _insertar(self, nodo, valor):
        if nodo is None:
            return Nodo(valor)
        if valor < nodo.valor:
            nodo.izquierda = self._insertar(nodo.izquierda, valor)
        elif valor > nodo.valor:
            nodo.derecha = self._insertar(nodo.derecha, valor)
        return nodo

    def __contains__(self, valor):
        nodo = self.raiz
        while nodo is not None:
            if valor == nodo.valor:
                return True
            nodo = nodo.izquierda if valor < nodo.valor else nodo.derecha
        return False

    def __iter__(self):
        yield from self._en_orden(self.raiz)

    def _en_orden(self, nodo):
        if nodo is not None:
            yield from self._en_orden(nodo.izquierda)
            yield nodo.valor
            yield from self._en_orden(nodo.derecha)

