class TablaHash:
    """Diccionario casero con encadenamiento: cada casilla es una lista de pares."""

    def __init__(self, casillas=8):
        self._casillas = [[] for _ in range(casillas)]

    def _indice(self, clave):
        return hash(clave) % len(self._casillas)

    def poner(self, clave, valor):
        casilla = self._casillas[self._indice(clave)]
        for par in casilla:
            if par[0] == clave:
                par[1] = valor
                return
        casilla.append([clave, valor])

    def obtener(self, clave):
        for k, v in self._casillas[self._indice(clave)]:
            if k == clave:
                return v
        raise KeyError(clave)


