class TablaHash:
    def __init__(self, casillas=8):
        self._casillas = [[] for _ in range(casillas)]

    def _indice(self, clave):
        return hash(clave) % len(self._casillas)

    def poner(self, clave, valor):
        casilla = self._casillas[self._indice(clave)]
        for par in casilla:
            if par[0] == clave:
                par[1] = valor
                return
        casilla.append([clave, valor])

    def obtener(self, clave):
        for k, v in self._casillas[self._indice(clave)]:
            if k == clave:
                return v
        raise KeyError(clave)

    def claves(self):
        return [par[0] for casilla in self._casillas for par in casilla]


texto = "café bus café almuerzo bus café pan"
conteo = TablaHash()
for palabra in texto.split():
    try:
        conteo.poner(palabra, conteo.obtener(palabra) + 1)
    except KeyError:
        conteo.poner(palabra, 1)

resultado = sorted(conteo.claves(), key=lambda p: (-conteo.obtener(p), p))
