from functools import wraps


def recordar(funcion):
    cache = {}

    @wraps(funcion)
    def envoltura(*args):
        if args in cache:
            return cache[args]
        envoltura.ejecuciones += 1
        resultado = funcion(*args)
        cache[args] = resultado
        return resultado

    envoltura.ejecuciones = 0
    return envoltura


@recordar
def fibonacci(n):
    """Devuelve el n-ésimo número de Fibonacci."""
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)


