import json
import os
from dataclasses import dataclass, asdict, field
from datetime import date


class ErrorBiblioteca(Exception): ...
class LibroNoDisponible(ErrorBiblioteca): ...
class LimiteDePrestamos(ErrorBiblioteca): ...
class NoEncontrado(ErrorBiblioteca): ...


@dataclass
class Libro:
    isbn: str
    titulo: str
    autor: str
    disponible: bool = True

@dataclass
class Socio:
    cedula: str
    nombre: str
    prestamos_activos: list[str] = field(default_factory=list)

@dataclass
class Prestamo:
    isbn: str
    cedula: str
    fecha: str
    devuelto: bool = False


class Biblioteca:
    MAX_PRESTAMOS = 3

    def __init__(self) -> None:
        self.libros: dict[str, Libro] = {}
        self.socios: dict[str, Socio] = {}
        self.prestamos: list[Prestamo] = []

    def agregar_libro(self, libro: Libro) -> None:
        if libro.isbn in self.libros:
            raise ValueError(f'ISBN {libro.isbn} repetido')
        self.libros[libro.isbn] = libro

    def agregar_socio(self, socio: Socio) -> None:
        if socio.cedula in self.socios:
            raise ValueError(f'cedula {socio.cedula} repetida')
        self.socios[socio.cedula] = socio

    def prestar(self, isbn: str, cedula: str, hoy: str | None = None) -> Prestamo:
        libro = self.libros.get(isbn)
        socio = self.socios.get(cedula)
        if libro is None or socio is None:
            raise NoEncontrado(f'libro {isbn} o socio {cedula} no existe')
        if not libro.disponible:
            raise LibroNoDisponible(f'{libro.titulo} ya esta prestado')
        if len(socio.prestamos_activos) >= self.MAX_PRESTAMOS:
            raise LimiteDePrestamos(f'{socio.nombre} ya tiene {self.MAX_PRESTAMOS} prestamos')
        libro.disponible = False
        socio.prestamos_activos.append(isbn)
        prestamo = Prestamo(isbn, cedula, hoy or str(date.today()))
        self.prestamos.append(prestamo)
        return prestamo

    def devolver(self, isbn: str, cedula: str) -> None:
        for p in self.prestamos:
            if p.isbn == isbn and p.cedula == cedula and not p.devuelto:
                p.devuelto = True
                self.libros[isbn].disponible = True
                self.socios[cedula].prestamos_activos.remove(isbn)
                return
        raise NoEncontrado('no hay un prestamo activo con esos datos')

    def a_dict(self) -> dict:
        return {'libros': [asdict(l) for l in self.libros.values()],
                'socios': [asdict(s) for s in self.socios.values()],
                'prestamos': [asdict(p) for p in self.prestamos]}

    @classmethod
    def desde_dict(cls, datos: dict) -> 'Biblioteca':
        b = cls()
        for d in datos.get('libros', []):
            b.libros[d['isbn']] = Libro(**d)
        for d in datos.get('socios', []):
            b.socios[d['cedula']] = Socio(**d)
        b.prestamos = [Prestamo(**d) for d in datos.get('prestamos', [])]
        return b

    def guardar(self, ruta: str) -> None:
        with open(ruta, 'w', encoding='utf-8') as f:
            json.dump(self.a_dict(), f, ensure_ascii=False, indent=2)

    @classmethod
    def cargar(cls, ruta: str) -> 'Biblioteca':
        try:
            with open(ruta, encoding='utf-8') as f:
                return cls.desde_dict(json.load(f))
        except FileNotFoundError:
            return cls()


b = Biblioteca()
b.agregar_libro(Libro('111', 'El Principito', 'Saint-Exupery'))
b.agregar_libro(Libro('222', 'Cocori', 'Joaquin Gutierrez'))
b.agregar_socio(Socio('1-1111-1111', 'Ana'))
