from dataclasses import dataclass
from datetime import date

DIAS_PRESTAMO = 14
MULTA_POR_DIA = 200


@dataclass
class Prestamo:
    isbn: str
    cedula: str
    fecha: str
    devuelto: bool = False


def dias_atraso(fecha_prestamo: str, hoy: str) -> int:
    transcurridos = (date.fromisoformat(hoy) - date.fromisoformat(fecha_prestamo)).days
    return max(0, transcurridos - DIAS_PRESTAMO)


class Biblioteca:
    def __init__(self) -> None:
        self.prestamos: list[Prestamo] = []

    def multas_pendientes(self, hoy: str) -> dict[str, int]:
        multas: dict[str, int] = {}
        for p in self.prestamos:
            if p.devuelto:
                continue
            multa = dias_atraso(p.fecha, hoy) * MULTA_POR_DIA
            if multa > 0:
                multas[p.cedula] = multas.get(p.cedula, 0) + multa
        return multas


assert dias_atraso('2026-11-01', '2026-11-27') == 12
assert dias_atraso('2026-11-20', '2026-11-27') == 0
assert dias_atraso('2026-11-13', '2026-11-27') == 0
assert dias_atraso('2026-11-12', '2026-11-27') == 1

