import sqlite3

ESQUEMA = """
CREATE TABLE IF NOT EXISTS categorias (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS gastos (
    id INTEGER PRIMARY KEY,
    fecha TEXT NOT NULL,
    descripcion TEXT NOT NULL,
    monto INTEGER NOT NULL CHECK (monto > 0),
    categoria_id INTEGER NOT NULL REFERENCES categorias(id),
    UNIQUE (fecha, descripcion, monto)
);
"""


class RepositorioGastos:
    def __init__(self, con):
        self.con = con
        con.execute("PRAGMA foreign_keys = ON")
        con.executescript(ESQUEMA)

    def agregar(self, gasto: Gasto) -> bool:
        """Inserta el gasto; devuelve False si ya existía uno igual."""
        self.con.execute("INSERT OR IGNORE INTO categorias (nombre) VALUES (?)", (gasto.categoria,))
        cid = self.con.execute("SELECT id FROM categorias WHERE nombre = ?", (gasto.categoria,)).fetchone()[0]
        cur = self.con.execute(
            "INSERT OR IGNORE INTO gastos (fecha, descripcion, monto, categoria_id) VALUES (?, ?, ?, ?)",
            (gasto.fecha, gasto.descripcion, gasto.monto, cid),
        )
        self.con.commit()
        return cur.rowcount == 1

    def cuantos(self) -> int:
        return self.con.execute("SELECT COUNT(*) FROM gastos").fetchone()[0]


def cargar(repo, gastos):
    return sum(repo.agregar(g) for g in gastos)


def test_cargar_dos_veces_no_duplica():
    repo = RepositorioGastos(sqlite3.connect(":memory:"))
    datos = [Gasto("2026-11-03", "comida", "Feria", 8500), Gasto("2026-11-20", "servicios", "Luz", 23000), Gasto("2026-12-02", "comida", "Super", 12400)]
    assert cargar(repo, datos) == 3
    assert cargar(repo, datos) == 0
    assert repo.cuantos() == 3


def test_gasto_distinto_si_entra():
    repo = RepositorioGastos(sqlite3.connect(":memory:"))
    repo.agregar(Gasto("2026-12-02", "comida", "Super", 12400))
    assert repo.agregar(Gasto("2026-12-02", "comida", "Super", 12401)) is True
    assert repo.cuantos() == 2


test_cargar_dos_veces_no_duplica()
test_gasto_distinto_si_entra()
