class RepositorioGastos:
    """Versión corta: solo lo necesario para las preguntas 1, 4 y 5 (el completo está en tu repositorio.py)."""

    def __init__(self, con):
        self.con = con
        con.execute("CREATE TABLE gastos (fecha TEXT, categoria TEXT, monto INTEGER)")

    def total_por_mes(self):
        return self.con.execute("SELECT substr(fecha, 1, 7) AS mes, SUM(monto) FROM gastos GROUP BY mes ORDER BY mes").fetchall()

    def promedio_por_categoria(self):
        return self.con.execute("SELECT categoria, COUNT(*), ROUND(AVG(monto), 0) FROM gastos GROUP BY categoria ORDER BY categoria").fetchall()

    def mayor_crecimiento_mensual(self):
        totales = self.total_por_mes()
        mejor = None
        for (mes_ant, t_ant), (mes, t) in zip(totales, totales[1:]):
            if mejor is None or t - t_ant > mejor[1]:
                mejor = (mes, t - t_ant)
        return mejor


class Preguntas:
