from dataclasses import dataclass


@dataclass
class Resultado:
    titulo: str
    encabezados: list[str]
    filas: list[tuple]

def formato(valor) -> str:
    if isinstance(valor, bool):
        return str(valor)
    if isinstance(valor, int):
        return f"{valor:,}"
    if isinstance(valor, float):
        return f"{valor:,.1f}"
    return str(valor)


def imprimir_tabla(resultado: Resultado, totales: bool = False) -> None:
    """Imprime el Resultado alineado: textos a la izquierda, números a la derecha."""
    filas = list(resultado.filas)
    if totales and filas:
        fila_total = []
        for i in range(len(resultado.encabezados)):
            columna = [f[i] for f in filas]
            fila_total.append(sum(columna) if all(isinstance(v, int) for v in columna) else "")
        fila_total[0] = "TOTAL"
        filas.append(tuple(fila_total))
    celdas = [[formato(v) for v in fila] for fila in filas]
    anchos = [len(e) for e in resultado.encabezados]
    for fila in celdas:
        for i, celda in enumerate(fila):
            anchos[i] = max(anchos[i], len(celda))
    numerica = [all(isinstance(f[i], (int, float)) for f in resultado.filas) for i in range(len(anchos))]

    def linea(valores):
        return "  ".join(v.rjust(anchos[i]) if numerica[i] else v.ljust(anchos[i]) for i, v in enumerate(valores))

    print(resultado.titulo)
    print(linea(resultado.encabezados))
    print("  ".join("-" * a for a in anchos))
    for fila in celdas:
        print(linea(fila))


def pregunta_2_acumulada(base: Resultado) -> Resultado:
    """Recibe el Resultado de la pregunta 2 (en el proyecto: Preguntas(repo).pregunta_2())."""
    acumulado = 0.0
    filas = []
    for fila in base.filas:
        acumulado += fila[2]
        filas.append(fila + (round(acumulado, 1),))
    return Resultado(base.titulo + " (acumulado)", base.encabezados + ["acumulado"], filas)


r2 = Resultado("2. Porcentaje del gasto por categoria", ["categoria", "total", "porcentaje"],
               [("servicios", 63900, 63.8), ("comida", 30700, 30.7), ("transporte", 5500, 5.5)])
r = pregunta_2_acumulada(r2)
imprimir_tabla(r, totales=True)
assert abs(r.filas[-1][3] - 100.0) < 0.1
print("Acumulado final correcto")

