def revisar(fuente: str) -> list[str]:
    """Lista funciones y clases sin docstring o con nombre fuera de la convención."""
    avisos = []
    for nodo in ast.walk(ast.parse(fuente)):
        if isinstance(nodo, (ast.FunctionDef, ast.ClassDef)):
            es_clase = isinstance(nodo, ast.ClassDef)
            patron = r"[A-Z][A-Za-z0-9]*" if es_clase else r"[a-z_][a-z0-9_]*"
            if not re.fullmatch(patron, nodo.name):
                avisos.append(f"{nodo.name}: nombre fuera de convencion")
            if ast.get_docstring(nodo) is None:
                avisos.append(f"{nodo.name}: sin docstring")
    return avisos


