class PresupuestoExcedido(Exception):
    pass


class Presupuesto:
    def __init__(self, limite: int):
        if limite <= 0:
            raise ValueError("El límite debe ser positivo")
        self.limite = limite
        self._gastado = 0

    @property
    def disponible(self) -> int:
        return self.limite - self._gastado

    def gastar(self, monto: int) -> None:
        if monto > self.disponible:
            raise PresupuestoExcedido(f"Quedan ₡{self.disponible:,} y quieres gastar ₡{monto:,}")
        self._gastado += monto

    def __str__(self) -> str:
        return f"Gastado ₡{self._gastado:,} de ₡{self.limite:,}"


