from collections import deque


def balanceado(texto: str) -> bool:
    pares = {")": "(", "]": "[", "}": "{"}
    pila = []
    for c in texto:
        if c in "([{":
            pila.append(c)
        elif c in pares:
            if not pila or pila.pop() != pares[c]:
                return False
    return not pila


def atender(fila: deque, n: int) -> list[str]:
    atendidos = []
    for _ in range(min(n, len(fila))):
        atendidos.append(fila.popleft())
    return atendidos


assert balanceado("{[()]}") and balanceado("f(x) + [1, 2]")
assert not balanceado("(]") and not balanceado("((") and not balanceado(")(")
fila = deque(["Ana", "Luis", "Marta", "Pedro"])
assert atender(fila, 2) == ["Ana", "Luis"]
fila.append("Sofía")
print(atender(fila, 10), "| quedan:", list(fila))
print(balanceado("{[(])}"))

def factorial(n: int) -> int:
    if n <= 1:
        return 1
    return n * factorial(n - 1)


def suma_lista(valores: list[int]) -> int:
    if not valores:
        return 0
    return valores[0] + suma_lista(valores[1:])


def busqueda_binaria(ordenada: list[int], objetivo: int, inicio: int = 0, fin: int | None = None, llamadas: list | None = None) -> int:
    if fin is None:
        fin = len(ordenada) - 1
    if llamadas is not None:
        llamadas.append(1)
    if inicio > fin:
        return -1
    medio = (inicio + fin) // 2
    if ordenada[medio] == objetivo:
        return medio
    if ordenada[medio] < objetivo:
        return busqueda_binaria(ordenada, objetivo, medio + 1, fin, llamadas)
    return busqueda_binaria(ordenada, objetivo, inicio, medio - 1, llamadas)


