class RepositorioGastos:
    def __init__(self, con):
        self.con = con
        con.executescript("""
            CREATE TABLE categorias (id INTEGER PRIMARY KEY, nombre TEXT UNIQUE);
            CREATE TABLE gastos (id INTEGER PRIMARY KEY, fecha TEXT, monto INTEGER, categoria_id INTEGER REFERENCES categorias(id));
            INSERT INTO categorias (nombre) VALUES ('comida'), ('servicios');
            INSERT INTO gastos (fecha, monto, categoria_id) VALUES ('2026-11-03', 8500, 1), ('2026-11-20', 23000, 2), ('2026-12-02', 12400, 1);
        """)

    SQL_PORCENTAJE = """
        SELECT c.nombre, SUM(g.monto), ROUND(SUM(g.monto) * 100.0 / (SELECT SUM(monto) FROM gastos), 1)
        FROM gastos g JOIN categorias c ON c.id = g.categoria_id
        GROUP BY c.nombre ORDER BY 2 DESC"""

    def porcentaje_por_categoria(self):
        return self.con.execute(self.SQL_PORCENTAJE).fetchall()


repo = RepositorioGastos(sqlite3.connect(":memory:"))
