def revisar_ensayo(plan: dict[str, int], ensayo: dict[str, int]) -> int:
    total = 0
    for parte, planeado in plan.items():
        real = ensayo[parte]
        total += real
        marca = "PASADO" if real > planeado + 10 else "ok"
        print(f"{parte:<20} plan {planeado:>3} s  real {real:>3} s  {marca}")
    print(f"Total: {total // 60}:{total % 60:02d} (meta 5:00)")
    return total


duracion = revisar_ensayo(PLAN, ENSAYO_1)
print("Hay que recortar", duracion - 300, "segundos")

